const b=$input.first().json.body??{};
const s=(v,m=500)=>typeof v==='string'?v.trim().slice(0,m):'';
const n=v=>(v===''||v===null||v===undefined)?null:(Number.isFinite(Number(v))?Number(v):null);
const errors=[],token=s(b.access_token,4096),goal_mode=s(b.goal_mode,30),goal_focus=s(b.goal_focus,30);
const weight=n(b.dumbbell_weight_kg),sets=n(b.sets),rir=n(b.rir),sport=s(b.cardio_sport,50)||'none';
const cardio=n(b.cardio_minutes??0),cal=n(b.daily_calories),sleep=n(b.sleep_hours),water=n(b.hydration_liters),stress=n(b.life_stress);
const meals=s(b.meals_summary,700);
let reps=Array.isArray(b.reps)?b.reps.map(Number):s(b.reps,100).split(',').map(x=>Number(x.trim()));
const focuses={lose_weight:['fat_loss','endurance'],gain_weight:['muscle_gain','strength'],maintain_weight:['','maintenance']};
if(token.length<20)errors.push('You are not signed in.');
if(!focuses[goal_mode]||!focuses[goal_mode].includes(goal_focus))errors.push('Choose a valid goal mode and matching goal focus.');
if(weight===null||weight<0.5||weight>100)errors.push('Dumbbell weight must be 0.5–100 kg.');
if(!Number.isInteger(sets)||sets<1||sets>10)errors.push('Sets must be a whole number from 1 to 10.');
if(!reps.length||reps.length>10||reps.some(x=>!Number.isInteger(x)||x<1||x>100))errors.push('Reps must be comma-separated whole numbers from 1 to 100.');
if(Number.isInteger(sets)&&reps.length!==sets)errors.push('Provide one reps value for each set.');
if(!Number.isInteger(rir)||rir<0||rir>5)errors.push('RIR must be a whole number from 0 to 5.');
if(cardio===null||cardio<0||cardio>600)errors.push('Cardio minutes must be 0–600.');
if(cardio>0&&sport==='none')errors.push('Choose a cardio sport when cardio minutes are above zero.');
if(cal===null||cal<0||cal>10000)errors.push('Daily calories must be 0–10000.');
if(sleep===null||sleep<0||sleep>24)errors.push('Sleep must be 0–24 hours.');
if(water===null||water<0||water>15)errors.push('Hydration must be 0–15 liters.');
if(!Number.isInteger(stress)||stress<1||stress>10)errors.push('Stress must be a whole number from 1 to 10.');
return [{json:{valid:errors.length===0,errors,token,overload:{goal_mode,goal_focus,dumbbell_weight_kg:weight,sets,reps,rir,cardio_sport:sport,cardio_minutes:cardio,daily_calories:cal,meals_summary:meals,sleep_hours:sleep,hydration_liters:water,life_stress:stress}}}];

