const raw=$input.first().json.output ?? $input.first().json;
let out=raw;
if(typeof raw==='string'){try{out=JSON.parse(raw)}catch(e){throw new Error('AI output was not valid JSON.');}}
if(out?.output && typeof out.output==='object') out=out.output;
const memberId=$('Verify Token').first().json.body.id;
const req=$('Validate Input').first().json.overload;
const p=$('Get Member Profile').first().json.body[0];
if(!out?.next_session || typeof out.next_session!=='object') throw new Error('AI output is missing next_session.');
const content={feature:'progressive_overload',evaluated_at:new Date().toISOString(),
goal_mode:req.goal_mode,goal_focus:req.goal_focus,
input_session:{exercise:'Dumbbell Biceps',dumbbell_weight_kg:req.dumbbell_weight_kg,sets:req.sets,reps_per_set:req.reps,rir:req.rir,cardio_sport:req.cardio_sport,cardio_minutes:req.cardio_minutes},
recovery_inputs:{daily_calories:req.daily_calories,meals_summary:req.meals_summary,sleep_hours:req.sleep_hours,hydration_liters:req.hydration_liters,life_stress:req.life_stress},
member_context:{age:p.age,weight_kg:p.weight_kg,bmi:p.bmi,goal:p.goal,experience_level:p.experience_level,risk_flags:p.risk_flags??[]},
evaluation:out};
const notes=[`overload ${req.goal_mode}/${req.goal_focus}`,`biceps ${req.dumbbell_weight_kg}kg`,`${req.sets} sets`,`reps ${req.reps.join(',')}`,`RIR ${req.rir}`,`cardio ${req.cardio_sport} ${req.cardio_minutes}min`,`sleep ${req.sleep_hours}h`,`stress ${req.life_stress}/10`].join('; ').slice(0,1000);
const row={member_id:memberId,plan_type:'overload',content,nutrition_estimate:null,request_notes:notes};
return [{json:{row,content,coach_message:String(out.coach_message??'').slice(0,1500)}}];
